import{O as e,d as t,p as n}from"./runtime-core.esm-bundler-jC72uHyJ.js";import{t as r}from"./app-fxBgVz1h.js";var i=JSON.parse(`{"path":"/AI%E7%9F%A5%E8%AF%86%E5%BA%93/agent/skills.html","title":"Agent Skills 是什么？和 Prompt、MCP 到底差在哪？","lang":"zh-CN","frontmatter":{"title":"Agent Skills 是什么？和 Prompt、MCP 到底差在哪？","description":"从工程视角聊 Agent Skills：它和 Prompt、Function Calling、MCP 的联系与边界，SKILL.md 怎么写才稳，延迟加载和渐进式披露怎么设计，以及写 Skill 最容易踩的坑。","category":"AI 应用开发","head":[["meta",{"name":"keywords","content":"Agent Skills,MCP,Function Calling,Prompt,AI Agent,智能体,延迟加载,上下文注入,SKILL.md"}]]},"git":{"createdTime":1787385570000,"updatedTime":1787385570000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":23.3,"words":6989},"filePathRelative":"AI知识库/agent/skills.md"}`),a={name:`skills.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<blockquote><p>本文转载自 <a href="https://javaguide.cn/ai/" target="_blank" rel="noopener noreferrer">JavaGuide《AI 应用开发》专栏</a>(作者:Snailclimb),原文:<a href="https://javaguide.cn/ai/agent/skills.html" target="_blank" rel="noopener noreferrer">https://javaguide.cn/ai/agent/skills.html</a>。著作权归原作者所有,本站按作者转载要求注明出处,仅供个人学习使用。</p></blockquote><p>一次 Code Review 可能要看架构、安全、性能和项目约定。临时把这些规则放进 Prompt，换个会话后又要重新粘贴。</p><p>全局项目约定可以留在 <code>AGENTS.md</code>；Review 的检查顺序、检查项和参考资料应随 Review 任务加载。Skill 为这部分内容提供了独立入口。</p><h2 id="agent-skills-是什么" tabindex="-1"><a class="header-anchor" href="#agent-skills-是什么"><span>Agent Skills 是什么？</span></a></h2><p>Skill 是可被 Agent 发现、按需读取的任务说明。接口返回格式、日志字段、慢 SQL 的排查路径、Review 的关注顺序，都可以写进 <code>SKILL.md</code>。</p><p>Skill 本身不提供工具能力。它解决的是“这类任务该按什么规则做”，由宿主在任务命中时把对应说明交给 Agent。</p><h2 id="skill-和-prompt、mcp、function-calling-有什么联系" tabindex="-1"><a class="header-anchor" href="#skill-和-prompt、mcp、function-calling-有什么联系"><span>Skill 和 Prompt、MCP、Function Calling 有什么联系？</span></a></h2><p>它们处在同一条执行链路的不同位置：Prompt 说明用户要做什么，Function Calling 发起动作，MCP 接入外部能力，Skill 规定完成任务时采用的流程和约束。</p><p>拿“帮我分析这份报表”这个请求来说，用户说的话是 <strong>Prompt</strong>。模型决定调用 <code>read_file</code> 并生成结构化参数时，用到的是 <strong>Function Calling</strong>；<code>read_file</code> 若由 MCP Server 提供，<strong>MCP</strong> 负责的是连接和协议。</p><p>“先确认字段含义，再找异常值，最后给业务结论，不要只堆统计指标”则属于 <strong>Skill</strong>。它描述处理顺序和约束，不替代前面的请求、调用方式或外部连接。</p><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/skill-prompt-function-calling-mcp-comparison.webp" alt=" Skill 和 Prompt、MCP、Function Calling 对比" tabindex="0" loading="lazy"><figcaption> Skill 和 Prompt、MCP、Function Calling 对比</figcaption></figure><p>放在一个真实链路里，大概是这样：</p><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/skill-agent-execution-link.webp" alt="Agent 执行链路" tabindex="0" loading="lazy"><figcaption>Agent 执行链路</figcaption></figure><ol><li>用户提出任务（Prompt）</li><li>宿主把可用 Skills 的简短描述放进上下文（Skill 元数据）</li><li>模型判断当前任务命中了某个 Skill（Skill 路由）</li><li>宿主再把完整 <code>SKILL.md</code> 加载进来（延迟加载）</li><li>模型按照 Skill 里的流程去调工具、读资料、写结果（执行）</li></ol><p>工具并不是 Skill 的必备部分。<a href="https://github.com/sanyuan0704/sanyuan-skills" target="_blank" rel="noopener noreferrer">sanyuan-skills</a> 里的 Code Review Expert 只规定从 SOLID、安全、性能等维度审查；<a href="https://github.com/obra/superpowers" target="_blank" rel="noopener noreferrer">Superpowers</a> 的 TDD Skill 则要求 Agent 跑测试、读取输出，再决定下一步。</p><p>因此，Function Calling 是执行动作时可能用到的能力，Skill 更接近一次按需的<strong>上下文注入</strong>。<code>load_skill()</code> 也是这个意义上的概念，不是跨平台统一的 API 名称；Claude Code、Cursor、Codex、Copilot 的发现和加载方式各不相同。</p><h2 id="⭐️skill-md-到底怎么写" tabindex="-1"><a class="header-anchor" href="#⭐️skill-md-到底怎么写"><span><a href="http://xn--SKILL-4x7c7836l.md" target="_blank" rel="noopener noreferrer">⭐️SKILL.md</a> 到底怎么写？</span></a></h2><h3 id="基本结构" tabindex="-1"><a class="header-anchor" href="#基本结构"><span>基本结构</span></a></h3><p>最小可用的 Skill 其实很简单，就是一个目录加一个 Markdown 文件 <code>SKILL.md</code>。</p><p><code>scripts/</code>、<code>references/</code>、<code>assets/</code> 这些都不是必需项，但复杂点的 Skill 经常会用到这些文件夹，例如 <code>scripts/</code> 中放一些 Skill 需要用到的脚本。</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-text"><span class="line"><span>skill-name/</span></span>
<span class="line"><span>├── SKILL.md          # 主文件，触发时加载</span></span>
<span class="line"><span>├── scripts/          # 实用脚本（执行，不需要加载到上下文）</span></span>
<span class="line"><span>├── references/       # 参考资料（按需加载）</span></span>
<span class="line"><span>└── assets/           # 模板和静态文件（按需加载）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一个 <code>SKILL.md</code> 包含两部分：</p><ol><li>前面是 <strong>YAML 前置元数据</strong>，告诉宿主“我是谁、什么时候该用我”；</li><li>后面是<strong>正文</strong>，写具体流程、约束、示例和失败处理。</li></ol><p>想要学 Skill 怎么写，我们直接看最顶级的开源 Skill 就好了。</p><p>这里我们以 <a href="https://github.com/obra/superpowers/blob/main/skills/test-driven-development/SKILL.md" target="_blank" rel="noopener noreferrer">Superpowers 的 TDD 技能</a>为例，</p><p>它的元数据只有两行：</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#ABB2BF;">---</span></span>
<span class="line"><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">test-driven-development</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Use when implementing any feature or bugfix, before writing implementation code</span></span>
<span class="line"><span style="color:#ABB2BF;">---</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>TDD 会涉及到 Red-Green-Refactor 循环，但这个 TDD Skill 的 description 压根没提到，就一句话说清楚什么时候该用。正文才展开讲具体怎么做，简化版如下：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;"># TDD</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">## Rule</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">Write a failing test before production code.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">If you did not watch the test fail, the test is not trusted.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">## Flow</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">1.</span><span style="color:#D19A66;"> **RED**</span><span style="color:#ABB2BF;">: Write one small failing test.</span></span>
<span class="line"><span style="color:#E5C07B;">2.</span><span style="color:#D19A66;"> **VERIFY RED**</span><span style="color:#ABB2BF;">: Run it. Confirm it fails for the expected reason.</span></span>
<span class="line"><span style="color:#E5C07B;">3.</span><span style="color:#D19A66;"> **GREEN**</span><span style="color:#ABB2BF;">: Write the smallest code to pass.</span></span>
<span class="line"><span style="color:#E5C07B;">4.</span><span style="color:#D19A66;"> **REFACTOR**</span><span style="color:#ABB2BF;">: Clean up without changing behavior.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">## Use For</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Features</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Bug fixes</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Refactoring</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Behavior changes</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">## Ask Before Skipping</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Throwaway prototypes</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Generated code</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">## Done Checklist</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Test written first</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Failure observed</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Minimal code added</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Tests pass</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="先看官方的-skill-creator" tabindex="-1"><a class="header-anchor" href="#先看官方的-skill-creator"><span>先看官方的 skill-creator</span></a></h3><p><a href="https://github.com/anthropics/skills/blob/main/skills/skill-creator/SKILL.md" target="_blank" rel="noopener noreferrer"><code>skill-creator</code></a> 是 Anthropic 官方 Skills 仓库提供的创建 Skill 的 Skill。它会先要求 Agent 确认任务、触发条件和边界，再决定哪些内容留在 <code>SKILL.md</code>，哪些拆到 <code>scripts/</code> 或 <code>references/</code>。</p><p>它体现了两个实际取舍：<code>description</code> 要能让宿主识别适用任务；可由脚本稳定执行的步骤和只在特定场景需要的长资料，应拆出主文件。Claude 官方帮助文档也建议将这类额外内容按需访问。</p><h3 id="元数据-frontmatter" tabindex="-1"><a class="header-anchor" href="#元数据-frontmatter"><span>元数据（Frontmatter）</span></a></h3><p>元数据决定 Skill 能不能被正确发现和触发。一般来说，至少要写清楚两个字段：<code>name</code> 和 <code>description</code>。</p><p><code>name</code> 就是 Skill 的标识，主要给系统和人定位用；<code>description</code> 则更像路由说明，告诉 Agent 什么时候该把这个 Skill 加载进来，也就是什么时候用。</p><p>先看 <code>name</code>。它有几个硬性要求：</p><ul><li>最多 64 个字符</li><li>只能包含小写字母、数字和连字符</li><li>不能包含 XML 标签</li><li>不能包含保留字，比如 <code>anthropic</code>、<code>claude</code></li></ul><p>命名时可以优先用动名词形式，也就是“动词 + -ing”。这样一眼就能看出这个 Skill 提供的是什么能力。</p><table><thead><tr><th><strong>好的命名</strong></th><th><strong>不好的命名</strong></th></tr></thead><tbody><tr><td><code>processing-pdfs</code></td><td><code>helper</code>、<code>utils</code>，太模糊</td></tr><tr><td><code>reviewing-code</code></td><td><code>documents</code>，太通用</td></tr><tr><td><code>test-driven-development</code></td><td><code>tools</code>，啥也没说</td></tr><tr><td><code>analyzing-spreadsheets</code></td><td><code>anthropic-helper</code>，包含保留字</td></tr></tbody></table><p><code>description</code> 更关键。如果<code>description</code> 写的不好，那这个Skill 就没办法在该调用的时候被调用。毕竟 Agent 不会先把每个 Skill 的 <code>SKILL.md</code> 都读一遍，而是先看描述来判断该不该加载。</p><p><code>description</code>的描述不能太简洁，也不要太多。一个好用的 <code>description</code>，建议说清楚两件事就足够了：</p><ol><li>这个 Skill 做什么</li><li>在什么场景下需要用它</li></ol><p>我们前面列举的 Superpowers 的 TDD 技能就是满足这个要求的。</p><p>最好再带上一些用户可能会说出来的词。比如 PDF、表单、提取、提交消息、git diff 这类词。这样不管是规则匹配还是语义匹配，都更容易抓到。</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#7F848E;font-style:italic;"># ✓ 好的：有能力、有场景、有触发词</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">从 PDF 文件中提取文本和表格、填充表单、合并文档。在处理 PDF 文件或用户提及 PDF、表单、文档提取时使用。</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✗ 避免：第一人称 + 触发条件不清楚</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">我可以帮助您处理 PDF 文件</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># ✗ 避免：只写能力，不写什么时候用</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">处理 Excel 文件</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看几个实际例子：</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#7F848E;font-style:italic;"># Superpowers 的 TDD</span></span>
<span class="line"><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">test-driven-development</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Use when implementing any feature or bugfix, before writing implementation code</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># sanyuan-skills 的 Code Review Expert</span></span>
<span class="line"><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">code-review-expert</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Expert code review of current git changes with a senior engineer lens. Detects SOLID violations, security risks, and proposes actionable improvements.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Git 提交助手</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">通过分析 git diff 生成描述性提交消息。当用户要求帮助编写提交消息或审查暂存更改时使用。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>只写概念、范围过宽或缺少触发条件的 <code>description</code>，例如：</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#7F848E;font-style:italic;"># Superpowers 的 TDD 反例，只写概念，不写触发时机</span></span>
<span class="line"><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">test-driven-development</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Helps with test-driven development and writing better tests.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Code Review Expert 反例，太泛</span></span>
<span class="line"><span style="color:#E06C75;">name</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">code-review-expert</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">Helps review code and improve quality.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># Git 提交助手反例，只写功能名</span></span>
<span class="line"><span style="color:#E06C75;">description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">生成提交消息。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="正文" tabindex="-1"><a class="header-anchor" href="#正文"><span>正文</span></a></h3><p>正文是 Agent 命中 Skill 后才会读取的操作说明。启动阶段通常只有 <code>name</code> 和 <code>description</code> 参与路由；正文加载后，会与系统提示、用户请求和已有资料共用上下文空间。</p><p>因此，正文只保留任务执行时需要的默认方案、项目约定、输入输出和失败处理。规则藏在大段科普里，Agent 需要时反而更难找到。</p><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/context-engineering/why-does-the-following-content-fail.png" alt="上下文为什么会失效" tabindex="0" loading="lazy"><figcaption>上下文为什么会失效</figcaption></figure><p>筛正文时可以依次确认：</p><ul><li>Agent 真的需要这段解释吗？</li><li>这是项目里的私有知识，还是通用常识？</li><li>这段话值不值得占用上下文？</li></ul><p>处理 PDF 文本时，正文直接给默认库和调用方式：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">## 提取 PDF 文本</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">使用 pdfplumber 进行文本提取：</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">\`\`\`python</span></span>
<span class="line"><span style="color:#C678DD;">import</span><span style="color:#ABB2BF;"> pdfplumber</span></span>
<span class="line"><span style="color:#C678DD;">with</span><span style="color:#ABB2BF;"> pdfplumber.</span><span style="color:#61AFEF;">open</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;file.pdf&quot;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> pdf:</span></span>
<span class="line"><span style="color:#ABB2BF;">    text </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> pdf.pages[</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">].</span><span style="color:#61AFEF;">extract_text</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">\`\`\`</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>从 PDF 定义和工具罗列开始的正文，对 Agent 的下一步没有帮助：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">## 提取 PDF 文本</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">PDF（便携式文档格式）是一种常见文件格式，通常包含文本、图片和其他内容。</span></span>
<span class="line"><span style="color:#ABB2BF;">如果要从 PDF 中提取文本，需要使用专门的 PDF 处理库。</span></span>
<span class="line"><span style="color:#ABB2BF;">目前有很多库可以完成这类工作，例如 pypdf、pdfplumber、PyMuPDF 等。</span></span>
<span class="line"><span style="color:#ABB2BF;">这里建议使用 pdfplumber，因为它比较容易上手，也能覆盖大多数普通 PDF 文本提取场景。</span></span>
<span class="line"><span style="color:#ABB2BF;">首先，你需要使用 pip 安装它，然后再编写下面的代码……</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Agent 需要的是默认使用什么、如何调用、输出如何处理，以及遇到特殊情况时怎么分支。项目里那些无法从通用知识推断出来的约束尤其要写清楚，例如：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#ABB2BF;">users 表使用软删除。所有正式查询都必须加 </span><span style="color:#E5C07B;">\`</span><span style="color:#98C379;">WHERE deleted_at IS NULL</span><span style="color:#E5C07B;">\`</span><span style="color:#ABB2BF;">。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这条约束会直接改变查询结果；软删除的通用定义无需放进 Skill：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#ABB2BF;">软删除是一种常见的数据删除方式，通常不会真正删除数据库记录，而是通过字段标记记录状态。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>主文件过长时，把只在特定步骤才用到的内容拆到单独文件。Anthropic 建议将 <code>SKILL.md</code> 正文尽量控制在 500 行以内，通过渐进式披露按需读取细节。</p><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/keep-skill-md-content-under-500-lines-for-best-performance.png" alt="SKILL.md 正文最好控制在 500 行以内" tabindex="0" loading="lazy"><figcaption><a href="http://SKILL.md" target="_blank" rel="noopener noreferrer">SKILL.md</a> 正文最好控制在 500 行以内</figcaption></figure><p>例如，Code Review Skill 的主文件只需指出何时读取 SOLID 检查项：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#ABB2BF;">需要做 SOLID 设计检查时，读取 </span><span style="color:#E5C07B;">\`</span><span style="color:#98C379;">references/solid-checklist.md</span><span style="color:#E5C07B;">\`</span><span style="color:#ABB2BF;">。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>references/solid-checklist.md</code> 保存具体 checklist；任务不涉及设计检查时，Agent 不必读取它。</p><p>这些开源 Skill 集合展示了主文件与参考资料的拆分方式：</p><ul><li><a href="https://github.com/obra/superpowers" target="_blank" rel="noopener noreferrer">Superpowers</a>：包含 TDD、brainstorming、代码审查等 Skill，TDD 那个结构很清楚，适合看正文怎么组织。</li><li><a href="https://github.com/sanyuan0704/sanyuan-skills" target="_blank" rel="noopener noreferrer">sanyuan-skills</a>：Code Review Expert 把更细的检查项拆进 <code>references/</code>，主文件只保留触发和加载说明，适合作为渐进式披露的例子。</li><li><a href="https://github.com/anthropics/skills" target="_blank" rel="noopener noreferrer">Anthropic 官方 Skills 仓库</a>：目录结构和写法可以作为基准参考。</li></ul><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/skillssh.png" alt="查找自己需要和热门的 Skills" tabindex="0" loading="lazy"><figcaption>查找自己需要和热门的 Skills</figcaption></figure><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/superpowers-skills.png" alt="Superpowers 内置的 skills" tabindex="0" loading="lazy"><figcaption>Superpowers 内置的 skills</figcaption></figure><p>在 Claude Code 这类工具中，可以用 <code>/skill-name</code> 主动调用，也可以让模型根据任务选择；触发后再读取流程、约束、脚本和参考文件。</p><h2 id="自由度怎么把控" tabindex="-1"><a class="header-anchor" href="#自由度怎么把控"><span>自由度怎么把控？</span></a></h2><p>数据库迁移和生产部署要在 Skill 中固定命令、参数、校验与回滚条件；这类操作出错后往往要恢复数据或服务状态。</p><p>代码审查和技术方案评估需要结合变更内容判断。Skill 固定安全、性能、可维护性和项目约定这些检查维度即可，无需为每个文件指定顺序。</p><p>下表按任务风险划分自由度：</p><table><thead><tr><th><strong>自由度</strong></th><th><strong>适合场景</strong></th><th><strong>写法</strong></th></tr></thead><tbody><tr><td>高</td><td>需要判断和取舍，答案不唯一</td><td>给检查方向，不写死步骤</td></tr><tr><td>中</td><td>有固定模板，但允许按场景调整</td><td>给模板、参数和边界</td></tr><tr><td>低</td><td>操作脆弱，出错代价高</td><td>给精确命令，明确不能改</td></tr></tbody></table><p>Superpowers 的 TDD Skill 固定了流程顺序：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-text"><span class="line"><span>NO PRODUCTION CODE WITHOUT A FAILING TEST FIRST</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>Red、Green、Refactor 不能调换；实现前必须先看到预期的失败。该 Skill 还写明：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-text"><span class="line"><span>Write code before the test? Delete it. Start over.</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>测试对象、名称和断言则由当前功能决定。Code Review 的检查框架也可以固定为 SOLID、安全风险、性能和可维护性，具体问题仍由 Agent 根据 diff 判断。</p><p>低自由度的写法可以这样：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">## 数据库迁移</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">运行下面这条命令：</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">\`\`\`bash</span></span>
<span class="line"><span style="color:#61AFEF;">python</span><span style="color:#98C379;"> scripts/migrate.py</span><span style="color:#D19A66;"> --verify</span><span style="color:#D19A66;"> --backup</span></span>
<span class="line"><span style="color:#ABB2BF;">\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">不要修改命令，不要添加额外参数。</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">如果命令失败，停止执行，并把错误输出返回给用户。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>代码审查这类任务可以只给检查范围：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">## 代码审查</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">重点检查：</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">1.</span><span style="color:#ABB2BF;"> 是否有明显 Bug 或边界情况遗漏</span></span>
<span class="line"><span style="color:#E5C07B;">2.</span><span style="color:#ABB2BF;"> 是否存在安全风险</span></span>
<span class="line"><span style="color:#E5C07B;">3.</span><span style="color:#ABB2BF;"> 是否影响性能或资源使用</span></span>
<span class="line"><span style="color:#E5C07B;">4.</span><span style="color:#ABB2BF;"> 是否违反项目已有约定</span></span>
<span class="line"><span style="color:#E5C07B;">5.</span><span style="color:#ABB2BF;"> 是否有更简单的实现方式</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">输出时优先写会影响正确性和线上稳定性的问题，不要只做格式建议。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这里没有指定文件顺序，但限定了审查范围和输出重点。改数据、发请求、部署、迁移或删除文件时收紧自由度；分析、评审、总结和生成草稿保留判断空间。</p><h2 id="⭐️延迟加载与渐进式披露" tabindex="-1"><a class="header-anchor" href="#⭐️延迟加载与渐进式披露"><span>⭐️延迟加载与渐进式披露</span></a></h2><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/agent-skills-progressive-disclosure.webp" alt="Skill 渐进式披露" tabindex="0" loading="lazy"><figcaption>Skill 渐进式披露</figcaption></figure><h3 id="为什么不能把所有-skill-一次性全塞进去" tabindex="-1"><a class="header-anchor" href="#为什么不能把所有-skill-一次性全塞进去"><span>为什么不能把所有 Skill 一次性全塞进去？</span></a></h3><p>Agent 的上下文窗口是有限的，至少现在还是这样。</p><p>而且，窗口大了只是能装下更多内容，不代表它能自动挑出重点。比如你给它分析一份长需求文档，真正关键的限制条件可能就三句话，但夹在各种背景和说明中，模型很容易忽略中间的那些关键句。</p><p>这就是大家常说的 <strong>Context Rot</strong>，上下文腐化。<strong>上下文越长，信息越杂，模型利用上下文的稳定性就越可能变差。</strong></p><p>跟它相关的还有一个经典现象叫 <strong>Lost in the Middle</strong>——模型对开头和结尾的信息更敏感，对夹在中间的东西更容易“看漏”。所以有时候你明明把资料给它了，它还是答错，不一定是没读到，而是关键内容在长上下文里不够显眼。</p><p>所以，Skill 不应该写成资料库。</p><p>更好的方式是渐进式披露：<strong>先给模型一份轻量目录，真正用到哪块，再去加载哪块。</strong></p><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/skills-progressive-disclosure.svg" alt="渐进式披露" tabindex="0" loading="lazy"><figcaption>渐进式披露</figcaption></figure><p>就像查书一样。你不会先把整本书背下来，而是先看目录，确定章节，再翻到具体那一页。</p><p>一般可以分成三层：</p><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/skills-progressive-disclosure-three-layer-model.png" alt="渐进式披露（三层模型）" tabindex="0" loading="lazy"><figcaption>渐进式披露（三层模型）</figcaption></figure><p><strong>1. 广告层：先让模型知道有这个 Skill</strong></p><p>启动时通常只加载 Skill 的元数据，比如 <code>name</code> 和 <code>description</code>。这部分很短，用来告诉模型：我是谁，我适合什么场景。</p><p><strong>2. 指令层：命中后再读正文</strong></p><p>当 Agent 判断当前任务确实相关时，才读取对应的 <code>SKILL.md</code> 正文。正文里放流程、规则、边界和关键示例。这里不要写太长，Anthropic 的建议是正文尽量控制在 500 行以内。</p><p><strong>3. 资源层：执行时再读细节</strong></p><p>如果正文里引用了 <code>references/</code>、<code>scripts/</code> 这类文件，Agent 再按需读取或执行。比如只是执行脚本，通常只需要把脚本输出放进上下文；如果要阅读或修改脚本，那源码才需要进上下文。</p><p>所以你会经常看到这种写法：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">## 高级功能</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">**表单填充**</span><span style="color:#ABB2BF;">：完整指南请参阅 [</span><span style="color:#61AFEF;">FORMS.md</span><span style="color:#ABB2BF;">]</span><span style="color:#E06C75;">(</span><span style="color:#C678DD;text-decoration:underline;">FORMS.md</span><span style="color:#E06C75;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">**API 参考**</span><span style="color:#ABB2BF;">：所有方法请参阅 [</span><span style="color:#61AFEF;">REFERENCE.md</span><span style="color:#ABB2BF;">]</span><span style="color:#E06C75;">(</span><span style="color:#C678DD;text-decoration:underline;">REFERENCE.md</span><span style="color:#E06C75;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>任务命中表单填充时，Agent 才读取 <code>FORMS.md</code>；普通文本提取无需加载该文件。</p><h3 id="实际项目中怎么组织文件" tabindex="-1"><a class="header-anchor" href="#实际项目中怎么组织文件"><span>实际项目中怎么组织文件？</span></a></h3><p>以一个数据分析类 Skill 为例，可以这么拆：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-text"><span class="line"><span>bigquery-analysis/</span></span>
<span class="line"><span>├── SKILL.md              # 概述和导航，命中时加载</span></span>
<span class="line"><span>└── reference/</span></span>
<span class="line"><span>    ├── finance.md        # 收入、ARR、账单指标</span></span>
<span class="line"><span>    ├── sales.md          # 机会、管道、账户</span></span>
<span class="line"><span>    ├── product.md        # API 使用、功能采用</span></span>
<span class="line"><span>    └── marketing.md      # 活动、归因、电子邮件</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>主文件只列出可用数据集和对应资料，数据口径留在各自的参考文件中：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;"># BigQuery 数据分析</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">## 可用数据集</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">**财务**</span><span style="color:#ABB2BF;">：收入、ARR、账单 → 参阅 [</span><span style="color:#61AFEF;">reference/finance.md</span><span style="color:#ABB2BF;">]</span><span style="color:#E06C75;">(</span><span style="color:#C678DD;text-decoration:underline;">reference/finance.md</span><span style="color:#E06C75;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">**销售**</span><span style="color:#ABB2BF;">：机会、管道、账户 → 参阅 [</span><span style="color:#61AFEF;">reference/sales.md</span><span style="color:#ABB2BF;">]</span><span style="color:#E06C75;">(</span><span style="color:#C678DD;text-decoration:underline;">reference/sales.md</span><span style="color:#E06C75;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">**产品**</span><span style="color:#ABB2BF;">：API 使用、功能采用 → 参阅 [</span><span style="color:#61AFEF;">reference/product.md</span><span style="color:#ABB2BF;">]</span><span style="color:#E06C75;">(</span><span style="color:#C678DD;text-decoration:underline;">reference/product.md</span><span style="color:#E06C75;">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">**营销**</span><span style="color:#ABB2BF;">：活动、归因、电子邮件 → 参阅 [</span><span style="color:#61AFEF;">reference/marketing.md</span><span style="color:#ABB2BF;">]</span><span style="color:#E06C75;">(</span><span style="color:#C678DD;text-decoration:underline;">reference/marketing.md</span><span style="color:#E06C75;">)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用户问“上个季度的销售管道怎么样”时，Agent 只需打开 <code>reference/sales.md</code>；财务、产品和营销资料无需加载。</p><p>必需规则经过多层引用后，Agent 很难直接定位：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#ABB2BF;">SKILL.md → advanced.md → details.md → 最关键的规则藏在这里</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>把基本用法和下一层资料都列在主文件里：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#ABB2BF;">SKILL.md</span></span>
<span class="line"><span style="color:#ABB2BF;">├── 直接包含基本用法</span></span>
<span class="line"><span style="color:#ABB2BF;">├── 高级功能 → advanced.md</span></span>
<span class="line"><span style="color:#ABB2BF;">└── API 参考 → reference.md</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Agent 读取主文件后即可定位资料。参考文件较长时，在文件开头列出目录，方便先确认可用内容。</p><h2 id="工作流和反馈循环怎么设计" tabindex="-1"><a class="header-anchor" href="#工作流和反馈循环怎么设计"><span>工作流和反馈循环怎么设计？</span></a></h2><p>简单点的任务，写几条规则就够用了。但遇到复杂一些的场景，这样做就不太够了。</p><p>Agent 很可能会跳过一些步骤，例如检查输出质量、跑测试代码，然后直接说它已经做完了。</p><p>为了避免这种问题，需要写清楚这两个点：</p><ol><li>每一步按什么顺序走</li><li>哪些地方必须停下来验证</li></ol><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/agent-skills-workflow-design.webp" alt="Skill 工作流设计" tabindex="0" loading="lazy"><figcaption>Skill 工作流设计</figcaption></figure><p>图示：复杂 Skill 要把任务分类、条件分支、验证节点和失败兜底写进流程里。</p><h3 id="用清单把步骤串起来" tabindex="-1"><a class="header-anchor" href="#用清单把步骤串起来"><span>用清单把步骤串起来</span></a></h3><p>Superpowers 的 TDD Skill 就是一个很好的例子。</p><p>它没有只写一句“先写测试，再写代码”。这种话太粗了，Agent 真执行时还是容易糊弄过去。</p><p>它是直接把流程拆成了几个明确阶段，简化版本如下：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">### RED - Write Failing Test</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">Write one minimal test showing what should happen.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">### Verify RED - Watch It Fail</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">**MANDATORY. Never skip.**</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">Confirm:</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Test fails, not errors</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Failure message is expected</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Fails because feature missing, not typos</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">### GREEN - Minimal Code</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">Write simplest code to pass the test.</span></span>
<span class="line"><span style="color:#ABB2BF;">Don&#39;t add features.</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E06C75;">### REFACTOR - Clean Up</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">After green only:</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Remove duplication</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Improve names</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> Extract helpers</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">Keep tests green. Don&#39;t add behavior.</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Verify RED</strong> 规定：Agent 必须先看到预期的失败，再开始实现。</p><p>失败应由功能尚未实现引起，而非路径、语法或测试本身的错误。</p><p>这一步如果不写清楚，Agent 很容易直接写实现，然后补一个“看起来能过”的测试。这就不是 TDD 了。</p><p>完成前的验证条件也写成清单：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">## Verification Checklist</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">Before marking work complete:</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Every new function/method has a test</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Watched each test fail before implementing</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Each test failed for expected reason</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Wrote minimal code to pass each test</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] All tests pass</span></span>
<span class="line"><span style="color:#E5C07B;">-</span><span style="color:#ABB2BF;"> [ ] Output has no errors or warnings</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>清单中的每一项都应是可核验的动作，例如“所有测试通过”或“每个新方法都有测试”。“保证质量”“遵循测试最佳实践”这类要求没有判定标准，无法作为验证节点。</p><h3 id="反馈循环" tabindex="-1"><a class="header-anchor" href="#反馈循环"><span>反馈循环</span></a></h3><p>复杂任务需要把中间验证节点写进流程：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-text"><span class="line"><span>运行 → 验证 → 修复 → 再验证</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>例如，代码审查若只要求“全面审查”，Agent 容易先处理命名、格式和注释，遗漏架构问题。</p><p>可以把审查拆成两轮：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">## 代码审查流程</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">1.</span><span style="color:#ABB2BF;"> 获取变更文件列表和 diff</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">2.</span><span style="color:#ABB2BF;"> 第一轮：设计审查</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 检查整体结构是否合理</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 检查是否违反 SOLID 原则</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 如果发现明显架构问题，先报告，不急着进入细节审查</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">3.</span><span style="color:#ABB2BF;"> 第二轮：实现审查</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 检查安全风险，比如 SQL 注入、XSS、越权</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 检查性能热点，比如循环里的 DB 调用、缺失索引</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 检查异常处理和边界条件</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">4.</span><span style="color:#ABB2BF;"> 输出问题</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 标注严重等级：Critical / Warning / Suggestion</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 给出可以直接修改的建议</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这份流程先检查设计，再检查实现，最后输出修改建议。</p><h3 id="条件分支" tabindex="-1"><a class="header-anchor" href="#条件分支"><span>条件分支</span></a></h3><p>Skill 同时处理多种任务时，应列出判断条件和分支。创建文档与编辑已有文档的处理路径不同：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;">## 文档修改工作流</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">1.</span><span style="color:#ABB2BF;"> 先判断任务类型</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">   **创建新文档？**</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">   走创建工作流。</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D19A66;">   **编辑现有文档？**</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">   走编辑工作流。</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">2.</span><span style="color:#ABB2BF;"> 创建工作流</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 使用模板生成文档</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 导出为目标格式</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 验证文件可以正常打开</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">3.</span><span style="color:#ABB2BF;"> 编辑工作流</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 解包现有文档</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 修改指定内容</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 每次修改后验证</span></span>
<span class="line"><span style="color:#E5C07B;">   -</span><span style="color:#ABB2BF;"> 完成后重新打包</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>分支多起来后，主文件保留判断逻辑，具体流程拆到单独文件：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-text"><span class="line"><span>workflows/</span></span>
<span class="line"><span>├── create-document.md</span></span>
<span class="line"><span>├── edit-document.md</span></span>
<span class="line"><span>└── export-document.md</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>任务命中哪个分支，Agent 就读取对应文件。流程规定执行顺序，反馈节点规定检查时机；缺少其中一项时，执行容易跳步。</p><h2 id="skill-路由怎么做" tabindex="-1"><a class="header-anchor" href="#skill-路由怎么做"><span>Skill 路由怎么做？</span></a></h2><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/agent-skills-routing-flow.webp" alt="Skill 路由流程" tabindex="0" loading="lazy"><figcaption>Skill 路由流程</figcaption></figure><p>用户提交“频繁 Full GC”时，路由器应选择 JVM 诊断 Skill，并排除数据库排查和文档处理 Skill。路由完成后，要得到可直接加载的 Skill 集合。</p><p>Skill 只有三五个时，模型读取 <code>description</code> 通常足以完成选择。数量增加到几十个后，按“召回候选 → 重新排序 → 作出决策”的流程处理更稳定：</p><table><thead><tr><th>阶段</th><th>输入与处理</th><th>输出</th></tr></thead><tbody><tr><td>粗召回</td><td>将请求与 Skill 的名称、<code>description</code>、典型 Query 样本向量化，按余弦相似度取 top-5。</td><td>少量候选 Skill</td></tr><tr><td>精排</td><td>比较名称、描述、示例的命中情况；安全、数据库等高风险 Skill 使用更高阈值。</td><td>按相关性和风险排序的候选</td></tr><tr><td>决策</td><td>最高分满足阈值则加载对应 Skill；分数整体偏低时不加载任何 Skill，走默认流程。</td><td>一个、多个或零个已选 Skill</td></tr></tbody></table><p>同一请求中包含互不依赖的任务时，先拆分任务再路由。例如“分析 GC 日志并改一份部署文档”至少涉及 JVM 诊断和文档编辑，不能用一个泛化 Skill 覆盖两条流程。</p><p>对“频繁 Full GC”这类请求，粗召回可能得到 <code>jvm-metrics-analyzer</code>、链路追踪和 K8s 事件查看三个候选；精排检查“Full GC”“堆栈”等示例后，JVM 诊断 Skill 排在首位。若请求只写“帮我处理一下”，没有足够的语义线索，路由器应保留默认流程，而不是猜测用户要做数据库迁移或生产操作。</p><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/skills-router.svg" alt="Skill 路由流程" tabindex="0" loading="lazy"><figcaption>Skill 路由流程</figcaption></figure><p>新 Skill 没有历史 Query 时，<code>description</code> 过于抽象会拉低召回质量。<a href="https://agentskills.io/specification" target="_blank" rel="noopener noreferrer">Agent Skills 规范</a>没有规定通用的 <code>triggers</code> frontmatter 字段，各宿主也不保证读取自定义字段。自行维护调度器时，把典型 Query 放进独立的路由索引：</p><div class="language-yaml line-numbers-mode" data-highlighter="shiki" data-ext="yaml" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-yaml"><span class="line"><span style="color:#E06C75;">skill</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">jvm-runtime-diagnosis</span></span>
<span class="line"><span style="color:#E06C75;">examples</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#ABB2BF;">  - </span><span style="color:#98C379;">&quot;接口卡死了&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">  - </span><span style="color:#98C379;">&quot;频繁 Full GC&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">  - </span><span style="color:#98C379;">&quot;帮我看看这段 Java 堆栈&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">  - </span><span style="color:#98C379;">&quot;服务 OOM 了怎么排查&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>自定义路由器将 <code>examples</code> 与 Skill 的 <code>name</code>、<code>description</code> 一起向量化。使用第三方宿主时，只使用它明确支持的字段；不要把这份路由索引写进所有 <code>SKILL.md</code>，更不要假设每个宿主都会读取它。</p><p>几十个 Skill 用 NumPy 在内存中计算相似度即可，耗时通常来自外部 embedding API。先缓存 Query 向量；数量增长到数百或数千后，再评估 ANN 索引或向量数据库。</p><p>通用调度器可拆成四个部分：</p><table><thead><tr><th>部分</th><th>职责</th></tr></thead><tbody><tr><td>注册中心</td><td>保存 Skill 元数据、路由索引和向量。</td></tr><tr><td>路由引擎</td><td>召回候选、计算分数并应用阈值。</td></tr><tr><td>加载器</td><td>按路由结果读取 <code>SKILL.md</code> 与必要的参考资料。</td></tr><tr><td>上下文装配器</td><td>将已加载的内容放入对应任务的上下文。</td></tr></tbody></table><p>路由引擎不负责读取 Skill 正文，加载器也不参与打分。这样更新正文不会改变召回结果，更换向量存储也无需改动加载逻辑。</p><h2 id="写-skill-时容易踩的坑" tabindex="-1"><a class="header-anchor" href="#写-skill-时容易踩的坑"><span>写 Skill 时容易踩的坑</span></a></h2><h3 id="把-skill-当项目-readme-写" tabindex="-1"><a class="header-anchor" href="#把-skill-当项目-readme-写"><span>把 Skill 当项目 README 写</span></a></h3><p>README 记录项目背景、安装和功能，读者可以自行判断下一步。Agent 执行任务时需要的是可操作的边界：何时使用、按什么顺序执行、哪些情况停止以及失败后如何处理。</p><figure><img src="https://oss.javaguide.cn/github/javaguide/ai/skills/keep-skill-md-content-under-500-lines-for-best-performance.png" alt="SKILL.md 正文最好控制在 500 行以内" tabindex="0" loading="lazy"><figcaption><a href="http://SKILL.md" target="_blank" rel="noopener noreferrer">SKILL.md</a> 正文最好控制在 500 行以内</figcaption></figure><h3 id="想把一个-skill-写得太全" tabindex="-1"><a class="header-anchor" href="#想把一个-skill-写得太全"><span>想把一个 Skill 写得太全</span></a></h3><p>把 JVM、数据库、K8s、网关和消息队列都放进一个“系统故障排查器”后，用户贴 GC 日志时，Agent 仍要在容器资源、网关日志和 JVM 规则间选择。按问题边界拆分后，输入能直接落到对应资料：</p><ul><li><code>jvm-metrics-analyzer</code>：只看 JVM 指标、GC、线程栈</li><li><code>distributed-trace-finder</code>：只根据 TraceId 追链路耗时</li><li><code>k8s-pod-event-viewer</code>：只看 Pod 状态、重启原因和事件记录</li></ul><p>GC 日志进入 JVM 指标 Skill，TraceId 进入链路追踪 Skill，Pod 重启进入 K8s 事件 Skill。每个 Skill 只维护一类问题所需的规则和资料。</p><h3 id="给-agent-太多选择" tabindex="-1"><a class="header-anchor" href="#给-agent-太多选择"><span>给 Agent 太多选择</span></a></h3><p>只罗列 pypdf、pdfplumber、PyMuPDF、pdf2image，Agent 无法判断普通 PDF 与扫描版 PDF 分别该走哪条路径，可能在文本 PDF 上误用 OCR：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;"># ✗ 不推荐：选择太多</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">你可以使用 pypdf、pdfplumber、PyMuPDF 或 pdf2image 处理 PDF。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>默认路径与例外条件应一起写出：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;"># ✓ 推荐：默认方案 + 兜底方案</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">默认使用 pdfplumber 提取文本。</span></span>
<span class="line"><span style="color:#ABB2BF;">如果是扫描版 PDF，需要 OCR，再改用 pdf2image + pytesseract。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Skill 应给出正常条件下的默认选择，并明确切换条件。</p><h3 id="术语别来回换" tabindex="-1"><a class="header-anchor" href="#术语别来回换"><span>术语别来回换</span></a></h3><p>同一对象在一份 Skill 中应保持同一个名称。例如前文使用“API 端点”后，后文不再改写为 URL、API 路由或路径。判断条件引用术语时，名称不一致会制造歧义。</p><h3 id="让-llm-做确定性工作" tabindex="-1"><a class="header-anchor" href="#让-llm-做确定性工作"><span>让 LLM 做确定性工作</span></a></h3><p>格式转换、精确计算、批量文件处理和改数据的操作交给脚本执行：</p><ul><li>LLM 更适合做判断：读懂任务、提取参数、决定下一步、解释结果。</li><li>脚本更适合做执行：解析文件、转换格式、批量处理、校验输出。</li></ul><p>读取必需输入文件时，脚本应返回明确错误，而不是创建空文件掩盖输入缺失：</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#7F848E;font-style:italic;"># ✓ 推荐：错误条件写清楚</span></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> process_file</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">path</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    try</span><span style="color:#ABB2BF;">:</span></span>
<span class="line"><span style="color:#C678DD;">        with</span><span style="color:#56B6C2;"> open</span><span style="color:#ABB2BF;">(path, </span><span style="color:#E06C75;font-style:italic;">encoding</span><span style="color:#56B6C2;">=</span><span style="color:#98C379;">&quot;utf-8&quot;</span><span style="color:#ABB2BF;">) </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> f:</span></span>
<span class="line"><span style="color:#C678DD;">            return</span><span style="color:#ABB2BF;"> f.</span><span style="color:#61AFEF;">read</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#C678DD;">    except</span><span style="color:#ABB2BF;"> FileNotFoundError </span><span style="color:#C678DD;">as</span><span style="color:#ABB2BF;"> exc:</span></span>
<span class="line"><span style="color:#C678DD;">        raise</span><span style="color:#ABB2BF;"> FileNotFoundError(</span></span>
<span class="line"><span style="color:#C678DD;">            f</span><span style="color:#98C379;">&quot;必需输入文件不存在：</span><span style="color:#D19A66;">{</span><span style="color:#ABB2BF;">path</span><span style="color:#D19A66;">}</span><span style="color:#98C379;">。请检查路径或先生成该文件。&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">        ) </span><span style="color:#C678DD;">from</span><span style="color:#ABB2BF;"> exc</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>下列写法只保留底层异常，Agent 无法据此判断该检查路径还是生成缺失文件：</p><div class="language-python line-numbers-mode" data-highlighter="shiki" data-ext="python" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-python"><span class="line"><span style="color:#7F848E;font-style:italic;"># ✗ 不推荐：直接崩，Agent 只能猜原因</span></span>
<span class="line"><span style="color:#C678DD;">def</span><span style="color:#61AFEF;"> process_file</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;font-style:italic;">path</span><span style="color:#ABB2BF;">):</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#56B6C2;"> open</span><span style="color:#ABB2BF;">(path).</span><span style="color:#61AFEF;">read</span><span style="color:#ABB2BF;">()</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配置参数应说明取值的约束：</p><div class="language-markdown line-numbers-mode" data-highlighter="shiki" data-ext="markdown" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-markdown"><span class="line"><span style="color:#E06C75;"># ✓ 推荐：能看出为什么这样配</span></span>
<span class="line"></span>
<span class="line"><span style="color:#ABB2BF;">REQUEST_TIMEOUT = 30 # HTTP 请求通常应在 30 秒内完成</span></span>
<span class="line"><span style="color:#ABB2BF;">MAX_RETRIES = 3 # 三次重试在可靠性和耗时之间比较均衡</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="总结" tabindex="-1"><a class="header-anchor" href="#总结"><span>总结</span></a></h2><p>回到开头的代码审查场景：Prompt 承载这次审查请求，Function Calling 发起工具调用，MCP 连接文件、数据库或 GitHub 等外部能力，Skill 保存审查的流程与约束。</p><p><code>description</code> 要同时标出任务和触发场景，正文则放项目约定、执行步骤、失败处理和验证点。主文件保留主流程，细节拆到 <code>references/</code>、<code>scripts/</code>；迁移、部署、删文件等操作必须收紧步骤，审查和方案评估保留必要的判断空间。</p><h2 id="参考" tabindex="-1"><a class="header-anchor" href="#参考"><span>参考</span></a></h2><ul><li>Anthropic 官方 Skills 仓库：<a href="https://github.com/anthropics/skills" target="_blank" rel="noopener noreferrer">https://github.com/anthropics/skills</a></li><li>Anthropic 官方 skill-creator：<a href="https://github.com/anthropics/skills/blob/main/skills/skill-creator/SKILL.md" target="_blank" rel="noopener noreferrer">https://github.com/anthropics/skills/blob/main/skills/skill-creator/SKILL.md</a></li><li>Superpowers：<a href="https://github.com/obra/superpowers" target="_blank" rel="noopener noreferrer">https://github.com/obra/superpowers</a></li><li>sanyuan-skills：<a href="https://github.com/sanyuan0704/sanyuan-skills" target="_blank" rel="noopener noreferrer">https://github.com/sanyuan0704/sanyuan-skills</a></li><li>Everything Claude Code：<a href="https://github.com/nicekid1/everything-claude-code" target="_blank" rel="noopener noreferrer">https://github.com/nicekid1/everything-claude-code</a></li><li><a href="http://skills.sh" target="_blank" rel="noopener noreferrer">skills.sh</a>（查找现成 Skills 的平台）：<a href="https://skills.sh/" target="_blank" rel="noopener noreferrer">https://skills.sh/</a></li></ul>`,197)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};